def _parse_minutes(s: str) -> float:
    """Parse a duration string like '5m', '30s', '7d' into minutes."""
    s = s.strip()
    if s.endswith("ms"):
        return float(s[:-2]) / 60_000
    if s.endswith("s"):
        return float(s[:-1]) / 60
    if s.endswith("m"):
        return float(s[:-1])
    if s.endswith("h"):
        return float(s[:-1]) * 60
    if s.endswith("d"):
        return float(s[:-1]) * 60 * 24
    return float(s)


